<?php

namespace App\Models;

use CodeIgniter\Model;

class AuthenticationModel extends Model
{
    protected $table = 'users';
    protected $primaryKey = 'user_id';

    /**
     * The submitted password is the MD5 digest generated by the existing login form.
     *
     * @return array<string, int|string>|null
     */
    public function authenticate(string $username, string $passwordHash): ?array
    {
        return $this->db->table('users')
            ->select('user_id, user_name, first_name, last_name')
            ->where('user_name', $username)
            ->where('password_enc', $passwordHash)
            ->where('activated', 1)
            ->get()
            ->getRowArray();
    }

    /**
     * @return array<string, int>
     */
    public function getPermissions(int $userId): array
    {
        $rows = $this->db->table('permissions p')
            ->select('p.name, up.value')
            ->join('user_permissions up', 'up.permission_id = p.permission_id')
            ->where('up.user_id', $userId)
            ->where('up.value', 1)
            ->get()
            ->getResultArray();

        $permissions = [];
        foreach ($rows as $row) {
            $permissions[$row['name']] = (int) $row['value'];
        }

        return $permissions;
    }

    /**
     * @return array<int, int>
     */
    public function getSeriesPermissions(int $userId): array
    {
        $rows = $this->db->table('user_series')
            ->select('competition_series_id')
            ->where('user_id', $userId)
            ->where('value', 1)
            ->get()
            ->getResultArray();

        $permissions = [];
        foreach ($rows as $row) {
            $permissions[(int) $row['competition_series_id']] = 1;
        }

        return $permissions;
    }
}
